with exploded as (select id, plan, effective_from, explode(tier_limits) as val from price_tiers), enriched as (select id, plan, effective_from, val, cume_dist() over (partition by plan order by val nulls first) as val_cume_dist from exploded), with_windows as (select id, plan, effective_from, val, val_cume_dist, rank() over (order by val desc nulls first) as val_rank, cume_dist() over (order by val) as val_cume_dist_2, count(val) over (partition by plan) as plan_count_val, percent_rank() over (partition by plan order by val desc nulls first) as val_percent_rank, rank() over (partition by plan order by val_cume_dist nulls last) as val_cume_dist_rank from enriched), metrics as (select *, dense_rank() over w_part as val_rank_dense_rank, min(val_cume_dist) over (partition by plan) as plan_min_val_cume_dist, cume_dist() over (partition by plan order by plan_count_val desc nulls first) as plan_count_val_cume_dist, rank() over (partition by plan order by val_rank) as val_rank_rank, dense_rank() over (order by val desc nulls first) as val_dense_rank from with_windows where effective_from > '2023-07-01' window w_part as (order by val_rank nulls first)), enriched_price_tiers as (select *, stddev_samp(val_rank) over (partition by plan) as plan_stddev_samp_val_rank, percent_rank() over (partition by plan order by val_rank desc nulls first) as val_rank_percent_rank from metrics), summary as (select date_trunc('week', effective_from) as week_start, case when plan_count_val >= 17 then 'HIGH' else 'LOW' end as plan_count_val_tier, percentile_approx(val_cume_dist, array(0.25, 0.5, 0.75)) as val_cume_dist_quartiles, count(case when plan = 'enterprise' then 1 end) as enterprise_count, round(avg(val_cume_dist_2), 2) as avg_val_cume_dist_2, percentile_approx(plan_min_val_cume_dist, 0.9) as plan_min_val_cume_dist_p90, count(distinct plan) as distinct_plans, grouping(date_trunc('week', effective_from)) as gid from enriched_price_tiers group by grouping sets ((date_trunc('week', effective_from), case when plan_count_val >= 17 then 'HIGH' else 'LOW' end), (date_trunc('week', effective_from)), ()) having plan_min_val_cume_dist_p90 >= 0) select week_start, plan_count_val_tier, val_cume_dist_quartiles, avg_val_cume_dist_2, plan_min_val_cume_dist_p90, distinct_plans, gid from summary order by plan_count_val_tier desc nulls last;
